package ktanesolver.module.modded.regular.blockbusters;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class BlockbustersSolverTest{private final BlockbustersSolver solver=new BlockbustersSolver();
	@Test void evaluatesEdgeworkLetters(){assertThat(BlockbustersSolver.legalLetters(bomb())).containsExactly('C','G','I','L','N','Y');}
	@Test void usesStaggeredForwardAndVerticalAdjacency(){assertThat(BlockbustersSolver.neighbors("A2")).containsExactly("A1","A3","B2","B3");assertThat(BlockbustersSolver.neighbors("B1")).containsExactly("B2","C1");assertThat(BlockbustersSolver.neighbors("B5")).containsExactly("B4","C4");assertThat(BlockbustersSolver.neighbors("D2")).containsExactly("D1","D3","E1","E2");}
	@Test void findsInitialAndNextSafeTilesAndRecordsFirstColumn(){ModuleEntity module=new ModuleEntity();BlockbustersOutput first=solve(module,List.of("ACDE","AAAAA","AAAA","AAAAA","AAAA"),List.of());assertThat(first.coordinate()).isEqualTo("A2");assertThat(module.getState().get("blockbustersInitialLetters")).isEqualTo(List.of("A","C","D","E"));BlockbustersOutput next=solve(module,List.of("A-DE","ACAAA","AAAA","AAAAA","AAAA"),first.nextPath());assertThat(next.coordinate()).isEqualTo("B2");assertThat(next.nextPath()).containsExactly("A2","B2");}
	@Test void reachingColumnEMarksSolved(){List<String>path=List.of("A2","B2","C2","D2");SolveResult<BlockbustersOutput>result=solver.solve(new RoundEntity(),bomb(),new ModuleEntity(),new BlockbustersInput(List.of("A-DE","A-A--","A-A-","A-AAA","CAAA"),path));assertThat(result).isInstanceOf(SolveSuccess.class);assertThat(((SolveSuccess<BlockbustersOutput>)result).output().coordinate()).isEqualTo("E1");assertThat(((SolveSuccess<BlockbustersOutput>)result).solved()).isTrue();}
	@Test void rejectsBrokenPathOrAmbiguousCandidates(){assertThat(solver.solve(new RoundEntity(),bomb(),new ModuleEntity(),new BlockbustersInput(List.of("ACDE","AAAAA","AAAA","AAAAA","AAAA"),List.of("A2","C2")))).isInstanceOf(SolveFailure.class);assertThat(solver.solve(new RoundEntity(),bomb(),new ModuleEntity(),new BlockbustersInput(List.of("CCDE","AAAAA","AAAA","AAAAA","AAAA"),List.of()))).isInstanceOf(SolveFailure.class);}
	@SuppressWarnings("unchecked")private BlockbustersOutput solve(ModuleEntity m,List<String>cols,List<String>path){return((SolveSuccess<BlockbustersOutput>)solver.solve(new RoundEntity(),bomb(),m,new BlockbustersInput(cols,path))).output();}private static BombEntity bomb(){BombEntity b=new BombEntity();b.setSerialNumber("ABC123");return b;}}
